defmodule Knowseek.Documents.Chunk do
  @moduledoc """
  A slice of a document's body. Chunks are the unit of search: each chunk
  has an embedding (semantic search) and a generated `search_vector`
  tsvector column (full-text search).
  """
  use Ecto.Schema

  @type t :: %__MODULE__{}

  @primary_key {:id, :binary_id, autogenerate: true}
  @foreign_key_type :binary_id
  schema "chunks" do
    field :position, :integer
    field :content, :string
    field :embedding, Pgvector.Ecto.Vector
    # Generated by Postgres from `content`. Only used inside query fragments.
    field :search_vector, :string, writable: :never, load_in_query: false

    belongs_to :document, Knowseek.Documents.Document

    timestamps(type: :utc_datetime)
  end
end
